def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 1:
            safe_bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, safe_bid))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(float(prev['bid']))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 300:
            rich_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = DAILY_SALARY * (0.28 + 0.22 * scarcity)

    if supply <= 17:
        base += 10.0
    elif supply >= 23:
        base -= 6.0

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.92)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.68)

    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.98)
    elif no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.78)

    if highest_prev > 0:
        if highest_prev >= 90:
            if hp > 4 and no_water_days == 0 and supply >= 20:
                base = min(base, DAILY_SALARY * 0.32)
            else:
                base = max(base, DAILY_SALARY * 0.82)
        elif highest_prev >= 65:
            if hp > 5 and supply >= 21:
                base = min(base, DAILY_SALARY * 0.4)
            else:
                base = max(base, min(highest_prev + 1.5, DAILY_SALARY * 0.88))
        else:
            target = max(avg_prev + 1.0, highest_prev + 0.5)
            base = max(base, min(target, DAILY_SALARY * 0.72))

    if desperate_count >= 2 and supply <= 18:
        base = max(base, DAILY_SALARY * 0.8)

    if rich_count >= 1 and day >= 7 and hp > 3:
        base = min(base, DAILY_SALARY * 0.6)

    reserve_floor = 0.0
    days_left = 10 - day
    if days_left > 0 and hp > 2:
        reserve_floor = max(0.0, days_left - 1) * 12.0
    affordable = max(0.0, budget - reserve_floor)
    if hp <= 2 or no_water_days >= 1:
        affordable = budget

    bid = min(base, affordable)
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.5)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine bid based on yesterday's highest pressure
    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If we are desperate (low HP), bid just above the highest previous to win
        if my_status['hp'] <= 2:
            target = min(my_status['budget'], max(DAILY_SALARY * 0.8, max_prev + 0.5))
            return target
        else:
            # Otherwise, undercut high bidders to save budget
            if max_prev >= DAILY_SALARY * 0.8:
                return min(my_status['budget'], DAILY_SALARY * 0.4)
            else:
                # If yesterday's bids were moderate, bid just enough to beat them
                return min(my_status['budget'], max(DAILY_SALARY * 0.5, max_prev + 1.0))
    # No previous data: default conservative bid
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.8)
    return min(my_status['budget'], DAILY_SALARY * 0.5)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 60.0
    if my_status['hp'] < 4:
        return min(my_status['budget'], avg_prev * 1.2)
    if supply < WATER_REQ:
        return min(my_status['budget'], avg_prev * 0.8)
    return min(my_status['budget'], max(40.0, avg_prev * 0.95))
